companies = list_companies({})
first = list_contacts({ page: 1 })
remaining = for page in list.range(2, first.total_pages + 1) {
  result = list_contacts({ page: page })
  return result.items
}
all_contacts = fold acc = first.items for page_items in remaining {
  return acc + page_items
}

domain_to_company = fold acc = {} for c in companies {
  return acc + { [c.domain]: c.name }
}

is_e164 = (p) => {
  return regex.test(p, "^\\+1\\d{10}$")
}

to_e164 = (p) => {
  digits = regex.replace(p, "[^0-9]", "")
  normalized = if text.starts_with(digits, "1") and text.length(digits) == 11 {
    return digits
  } else if text.length(digits) == 10 {
    return "1" + digits
  } else {
    return digits
  }
  return "+" + normalized
}

results = for contact in all_contacts {
  needs_phone = contact.phone != null and not is_e164(contact.phone)
  new_phone = to_e164(contact.phone) if needs_phone else null

  needs_company = (contact.company == null or contact.company == "") and contact.email != null
  domain = if needs_company {
    parts = text.split(contact.email, "@")
    return parts[1] if list.length(parts) >= 2 else null
  } else {
    return null
  }
  new_company = domain_to_company[domain] if domain != null and domain in domain_to_company else null
  will_fill_company = new_company != null

  updated = if needs_phone or will_fill_company {
    args_id = contact.id
    u = update_contact({
      id: args_id,
      phone: new_phone if needs_phone else null,
      company: new_company if will_fill_company else null
    })
    return u
  } else {
    return null
  }

  return {
    phone_fixed: needs_phone,
    company_filled: will_fill_company
  }
}

phones_fixed = fold acc = 0 for r in results {
  return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
  return acc + (1 if r.company_filled else 0)
}

submit = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, recorded: submit.recorded }

